<section class="page-heading"><div><span class="eyebrow">RIWAYAT</span><h1>Riwayat aktivitas</h1><p>Aktivitas penting ditampilkan dengan bahasa yang mudah dipahami.</p></div></section>
<section class="panel activity-panel"><form method="get" class="activity-filter"><div class="toolbar-search"><?= ui_icon('search') ?><input name="q" value="<?= e($filters['q']) ?>" placeholder="Cari pengguna atau aktivitas..."></div><select name="user_id"><option value="">Semua pengguna</option><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>" <?= (int)$filters['user_id']===(int)$u['id']?'selected':'' ?>><?= e(display_user_name($u['name'])) ?></option><?php endforeach;?></select><input type="date" name="date_from" value="<?= e($filters['date_from']) ?>"><input type="date" name="date_to" value="<?= e($filters['date_to']) ?>"><button class="btn btn-primary" type="submit">Tampilkan</button><a class="btn btn-secondary" href="/activity">Reset</a></form><div class="activity-timeline"><?php if(!$rows):?><div class="empty-state"><h3>Belum ada aktivitas</h3></div><?php else:foreach($rows as $r):?><article class="activity-item"><span class="activity-dot"></span><div class="activity-copy"><div><span class="activity-category"><?= e($r['category']) ?></span><time><?= e(format_date_id($r['created_at'],true)) ?></time></div><strong><?= e($r['description']) ?></strong><small><?= e(display_user_name($r['user_name']??'Sistem')) ?></small></div></article><?php endforeach;endif;?></div></section>
